/** Embed authoritative JSON as typed, publishable TypeScript without import attributes. */
const root = new URL('../', import.meta.url);
const check = Deno.args.includes('--check');
const stale: string[] = [];

async function read(path: string): Promise<unknown> {
  return JSON.parse(await Deno.readTextFile(new URL(path, root)));
}

async function emit(
  path: string,
  imports: string,
  entries: readonly { name: string; type: string; value: unknown }[],
): Promise<void> {
  const header = '// @generated by scripts/embed-token-assets.ts\n' +
    '// Do not edit. Run `deno task tokens:embed`. JSON sources remain authoritative.\n\n';
  const declarations: string[] = [];
  for (const { name, type, value } of entries) {
    const bytes = new TextEncoder().encode(JSON.stringify(value));
    const compressed = new Uint8Array(
      await new Response(
        new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip')),
      ).arrayBuffer(),
    );
    const encoded = btoa(Array.from(compressed, (byte) => String.fromCharCode(byte)).join(''));
    declarations.push(`export const ${name}: ${type} = JSON.parse(await new Response(
      new Blob([Uint8Array.from(atob(${JSON.stringify(encoded)}), (char) => char.charCodeAt(0))])
        .stream().pipeThrough(new DecompressionStream('gzip')),
    ).text());\n`);
  }
  const source = header + imports + '\n\n' + declarations.join('\n');
  const process = new Deno.Command(Deno.execPath(), {
    args: ['fmt', '--ext', 'ts', '-'],
    cwd: root,
    stdin: 'piped',
    stdout: 'piped',
    stderr: 'piped',
  }).spawn();
  const writer = process.stdin.getWriter();
  await writer.write(new TextEncoder().encode(source));
  await writer.close();
  const result = await process.output();
  if (result.code !== 0) throw new Error(new TextDecoder().decode(result.stderr));
  const content = new TextDecoder().decode(result.stdout);
  const target = new URL(path, root);
  if (check) {
    if (await Deno.readTextFile(target).catch(() => undefined) !== content) stale.push(path);
  } else {
    await Deno.mkdir(new URL('./', target), { recursive: true });
    await Deno.writeTextFile(target, content);
  }
}

const documents = ['primitives', 'semantic', 'presets', 'density', 'component'];
const sources: Record<string, unknown> = {};
for (const name of documents) {
  sources[`${name}.tokens.json`] = await read(`tokens/v2/${name}.tokens.json`);
}
for (const scheme of ['light', 'dark']) {
  sources[`themes/${scheme}.tokens.json`] = await read(`tokens/v2/themes/${scheme}.tokens.json`);
}
const assets = 'src/tokens/assets/';
await emit(
  assets + 'sources.generated.ts',
  "import type { TokenSources } from '../domain/resolve-tokens.ts';",
  [{
    name: 'tokenSources',
    type: 'TokenSources',
    value: { resolver: await read('tokens/v2/tokens.resolver.json'), documents: sources },
  }],
);
await emit(
  assets + 'schemas.generated.ts',
  "import type { AnySchemaObject } from 'npm:ajv@8.20.0';",
  [
    {
      name: 'formatSchema',
      type: 'AnySchemaObject',
      value: await read('tokens/schemas/format.json'),
    },
    {
      name: 'resolverSchema',
      type: 'AnySchemaObject',
      value: await read('tokens/schemas/resolver.json'),
    },
  ],
);
const collections = [];
for (
  const name of [
    'primitives',
    'scheme',
    'theme',
    'density',
    'base-gray',
    'base-accent',
    'studio-flavor',
  ]
) {
  collections.push(await read(`tokens/figma/${name}.json`));
}
await emit(
  assets + 'figma.generated.ts',
  "import type { FigmaCollection } from '../domain/token-contract.ts';",
  [
    { name: 'collections', type: 'readonly FigmaCollection[]', value: collections },
    {
      name: 'figmaIndex',
      type:
        '{ fileKey: string; exportDate: string; collections: { collection: string; file: string; modes: string[]; variableCount: number }[] }',
      value: await read('tokens/figma/index.json'),
    },
  ],
);
await emit(
  assets + 'legacy.generated.ts',
  "import type { LegacyTokenSource } from '../adapters/figma-token-source.ts';",
  [
    {
      name: 'legacy',
      type: 'LegacyTokenSource & { css: string; bridge: string; fontImports: string[] }',
      value: await read('tokens/legacy.json'),
    },
  ],
);
await emit(
  assets + 'quality.generated.ts',
  "import type { TokenContrastCoverage, TokenContrastExclusion } from '../domain/contrast-contract.ts';\nimport type { TokenRoleRegistry } from '../domain/check-token-names.ts';",
  [
    {
      name: 'pairs',
      type: 'TokenContrastCoverage & { version: number }',
      value: await read('tokens/contrast-pairs.json'),
    },
    {
      name: 'exclusions',
      type: '{ version: number; exclusions: readonly TokenContrastExclusion[] }',
      value: await read('tokens/contrast-exclusions.json'),
    },
    {
      name: 'roleRegistry',
      type: 'TokenRoleRegistry',
      value: await read('tokens/role-manifest.json'),
    },
  ],
);
await emit(assets + 'metadata.generated.ts', '', [
  {
    name: 'nameMigrations',
    type:
      '{ version: number; migrations: { collection: string; variable: string; originalCssVar: string; cssVar: string; reason: string }[] }',
    value: await read('tokens/name-migrations.json'),
  },
  {
    name: 'fontRequests',
    type: '{ version: number; families: Record<string, number[]> }',
    value: await read('tokens/font-requests.json'),
  },
]);
// Keep registry metadata separate from the much larger build-only token sources.
await emit(
  'registry.theme-items.generated.ts',
  "import type { RegistryItemDefinition } from './registry.schema.ts';",
  [
    {
      name: 'generatedThemes',
      type: 'RegistryItemDefinition[]',
      value: await read('registry/theme/theme-items.json'),
    },
  ],
);
if (stale.length) throw new Error(`Stale embedded token assets: ${stale.join(', ')}`);
console.log(`Token JSON embeddings ${check ? 'checked' : 'generated'}.`);
